mapper.sql:
WHERE t."アカウントID" = #{accountId}
  AND t."親TODOID" IS NULL

    AND (t."タイトル" ILIKE '%' || #{keyword} || '%' OR COALESCE(t."メモ", '') ILIKE '%' || #{keyword} || '%')


    AND t."状態コード" = #{status}


    AND t."優先度コード" = #{priority}


    AND t."状態コード" <> 'DONE'


    AND t."期限日" >= #{dueFrom}


    AND t."期限日" <= #{dueTo}

mapper.select:
SELECT FROM public."COM_TODO情報" WHERE "親TODOID" IN
#{parentId}
ORDER BY "表示順" ASC, "TODOID" ASC

SELECT count(*)
  FROM public."COM_TODO情報"
 WHERE "アカウントID" = #{accountId} AND "親TODOID" IS NULL AND "状態コード" = #{status}
